-- Certified and preferred are independent facts about the same pair (7.3).
-- A man can be certified in something he would rather not do, and prefer
-- something he is not yet certified for -- which is a training list nobody
-- had to compile. Certified is granted_at being set, so it becomes nullable.
ALTER TABLE user_skill
    MODIFY COLUMN granted_at DATETIME NULL DEFAULT NULL,
    ADD COLUMN is_preferred TINYINT(1) NOT NULL DEFAULT 0 AFTER skill_id,
    ADD COLUMN preferred_at DATETIME NULL DEFAULT NULL AFTER is_preferred;

